int bnep_add_connection(struct bnep_connadd_req *req, struct socket *sock)
{
    struct net_device *dev;
    int err = -EINVAL;

    if (!sock)
        return -EINVAL;

    dev = alloc_netdev(0, "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev)
        return -ENOMEM;

    if (req->src_type && req->src) {
        memcpy(dev->dev_addr, req->src, ETH_ALEN);
    }

    /* Check if a session already exists for the destination address */
    if (check_existing_session(req->dst)) {
        free_netdev(dev);
        return -EEXIST;
    }

    setup_session_structure(dev, req, sock);

    if (req->features & BNEP_FEAT_MULTICAST) {
        configure_multicast_filters(dev);
    }

    if (req->features & BNEP_FEAT_PROTO_FILTERING) {
        configure_protocol_filters(dev);
    }

    err = register_netdev(dev);
    if (err < 0) {
        free_netdev(dev);
        return err;
    }

    /* Create a kernel thread to handle the session */
    err = create_session_thread(dev);
    if (err < 0) {
        unregister_netdev(dev);
        free_netdev(dev);
        return err;
    }

    /* Update the request structure with the device name */
    snprintf(req->dev_name, IFNAMSIZ, "%s", dev->name);

    return 0;
}

int bnep_add_connection(struct bnep_connadd_req *req, struct socket *sock) {
    struct net_device *dev;
    int err;

    if (!sock) {
        return -EINVAL;
    }

    dev = alloc_netdev(0, "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev) {
        return -ENOMEM;
    }

    eth_hw_addr_random(dev);

    if (bnep_session_exists(req->dst)) {
        if (bnep_is_session_connected(req->dst)) {
            free_netdev(dev);
            return -EEXIST;
        }
    }

    req->session = kzalloc(sizeof(struct bnep_session), GFP_KERNEL);
    if (!req->session) {
        free_netdev(dev);
        return -ENOMEM;
    }

    if (req->config & BNEP_CONFIG_MULTICAST) {
        dev->flags |= IFF_MULTICAST;
    }

    if (req->config & BNEP_CONFIG_PROTO_FILTER) {
        bnep_init_protocol_filters(req->session);
    }

    err = register_netdev(dev);
    if (err < 0) {
        kfree(req->session);
        free_netdev(dev);
        return err;
    }

    err = kernel_thread(bnep_session_handler, req->session, 0);
    if (err < 0) {
        unregister_netdev(dev);
        kfree(req->session);
        free_netdev(dev);
        return err;
    }

    strcpy(req->dev_name, dev->name);
    return 0;
}

int bnep_connadd(struct bnep_connadd_req *req, struct socket *sock)
{
    struct net_device *dev;
    struct bnep_session *session;
    int err;

    if (!sock) {
        return -EINVAL;
    }

    dev = alloc_netdev(sizeof(struct bnep_session), "bnep%d", NET_NAME_UNKNOWN, ether_setup);
    if (!dev) {
        return -ENOMEM;
    }

    session = netdev_priv(dev);
    session->dev = dev;
    session->sock = sock;
    memcpy(session->src_addr, req->src_addr, BDADDR_SIZE);
    memcpy(session->dst_addr, req->dst_addr, BDADDR_SIZE);

    if (bnep_find_session(req->dst_addr)) {
        err = -EEXIST;
        goto err_out;
    }

    if (req->role != BNEP_ROLE_CSB) {
        session->role = req->role;
    } else {
        session->role = BNEP_ROLE_CMU;
    }

    ether_setup(dev);
    dev->flags |= IFF_POINTOPOINT | IFF_NOARP;

    if (register_netdev(dev)) {
        err = -EIO;
        goto err_out;
    }

    if (req->filter_multicast) {
        bnep_setup_multicast_filters(session);
    }

    if (req->filter_protocols) {
        bnep_setup_protocol_filters(session);
    }

    session->thread = kthread_run(bnep_session_handler, session, "bnep_session");
    if (IS_ERR(session->thread)) {
        err = PTR_ERR(session->thread);
        goto err_unregister;
    }

    memcpy(req->dev_name, dev->name, IFNAMSIZ);
    return 0;

err_unregister:
    unregister_netdev(dev);
err_out:
    free_netdev(dev);
    return err;
}
